/* ============================================================================
   07_ImportExcelData.sql  -  OPTIONAL one-time import of the supplied Excel templates
   Generated from: calibration plan 2026.xlsx, QA .FMT - 27 List of Monitoring&Measuring Equipments(MME).xls, QA .FMT - 29 Equipment History Card.xls
   Run after 05_SeedReferenceData.sql. Re-runnable: does nothing if the import was already applied.
   Assumptions (see docs/DATA_QUALITY_REPORT.md): calibration type = External; imported results are
   'Unverified' because the plan does not record pass/fail; plan year = year of the next due date.
   ============================================================================ */
USE [CalibrationManagement];
GO
SET QUOTED_IDENTIFIER ON;   -- required by the filtered indexes (SSMS default; sqlcmd needs it explicitly)
SET NOCOUNT ON;
GO
IF EXISTS (SELECT 1 FROM dbo.Equipment WHERE SourceDocument LIKE N'QA.FMT-28 plan 2026%' OR SourceDocument LIKE N'QA.FMT-27 list%')
